export enum DisplayScale {
  Count,
  Utilization,
  Length,
  Voltage,
}

export function formatReading(value: number, scale: DisplayScale): string {
  if (!Number.isFinite(value)) {
    throw new RangeError("Reading must be finite.");
  }

  switch (scale) {
    case DisplayScale.Utilization:
      return `${(value * 100).toFixed(0)} %`;
    case DisplayScale.Length:
      return `${value.toFixed(2)} km`;
    case DisplayScale.Voltage:
      return `${value.toFixed(3)} V`;
    case DisplayScale.Count:
    default:
      return `${String(value)} items`;
  }
}

