import { DisplayScale, formatReading } from "./solution";

function equal(actual: unknown, expected: unknown, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}
function throwsRange(fn: () => unknown, message: string): void {
  let error: unknown;
  try { fn(); } catch (caught) { error = caught; }
  if (!(error instanceof RangeError)) throw new Error(message);
}

equal(formatReading(42, DisplayScale.Count), "42 items", "count integer");
equal(formatReading(1.25, DisplayScale.Count), "1.25 items", "count decimal representation");
equal(formatReading(-0, DisplayScale.Count), "0 items", "ordinary negative-zero string representation");
equal(formatReading(0.125, DisplayScale.Utilization), "12.5 %", "utilization");
equal(formatReading(0, DisplayScale.Utilization), "0.0 %", "utilization trailing decimal");
equal(formatReading(12.3, DisplayScale.Length), "12.30 km", "length trailing decimals");
equal(formatReading(-2.5, DisplayScale.Length), "-2.50 km", "negative length");
equal(formatReading(7, DisplayScale.Voltage), "7.000 V", "voltage trailing decimals");
equal(formatReading(1.2344, DisplayScale.Voltage), "1.234 V", "voltage rounding down");
equal(formatReading(1.2346, DisplayScale.Voltage), "1.235 V", "voltage rounding up");
equal(formatReading(9.5, 999 as DisplayScale), "9.5 items", "unknown numeric scale falls back to count");

for (const value of [Number.NaN, Number.POSITIVE_INFINITY, Number.NEGATIVE_INFINITY]) {
  throwsRange(() => formatReading(value, DisplayScale.Count), `reject ${String(value)} for count`);
  throwsRange(() => formatReading(value, DisplayScale.Voltage), `reject ${String(value)} for fixed scale`);
}

equal(formatReading(3, DisplayScale.Length), "3.00 km", "calls have no shared mutable state");

